/**
 *
 * PanelIndicator is a component that displays an indicator inside a Panel.
 *
 * [Live Demo](https://www.primereact.org/panel/)
 *
 * @module PanelIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { PanelRootInstance } from './PanelRoot.types';
/**
 * Defines passthrough(pt) options type in PanelIndicator component.
 */
export type PanelIndicatorPassThroughType<E> = PassThroughType<PanelIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of PanelIndicator component.
 */
export interface PanelIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: PanelIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in PanelIndicator component.
 */
export interface PanelIndicatorProps extends BaseComponentProps<PanelIndicatorInstance, unknown, PanelIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the state of the panel. Valid values are:
     * - "open": Indicator is visible when the panel is expanded.
     * - "closed": Indicator is visible when the panel is collapsed.
     * - "always": Indicator is always visible.
     * @defaultValue 'always'
     */
    match?: 'open' | 'closed' | 'always' | undefined;
}
/**
 * Defines valid state in PanelIndicator component.
 */
export interface PanelIndicatorState {
}
/**
 * Defines the methods and properties exposed by PanelIndicator component.
 */
export interface PanelIndicatorExposes {
    /**
     * The Panel component instance.
     */
    panel: PanelRootInstance | undefined | null;
}
/**
 * Instance of PanelIndicator component.
 */
export type PanelIndicatorInstance = ComponentInstance<PanelIndicatorProps, PanelIndicatorState, PanelIndicatorExposes>;
